const screens={control:{src:'assets/controller.png',title:'수업의 흐름을 손끝에서.',alt:'이전·일시정지·다음 조작과 슬라이드 미리보기가 있는 수업 제어 화면',description:'일시정지, 이전·다음 슬라이드 이동까지. 진행 중인 수업을 한곳에서 제어합니다.'},editor:{src:'assets/editor.png',title:'시간과 화면을 우리 수업에 맞게.',alt:'운동 타이머와 슬라이드 표시 옵션을 편집하는 앱 화면',description:'운동·휴식 시간을 구성하고, 화면에 보여줄 내용을 미리 확인하세요.'},pairing:{src:'assets/pairing.png',title:'코드 하나로 연결되는 수업.',alt:'디스플레이 연결용 예시 QR과 코드 123456이 표시된 화면',description:'QR을 스캔하거나 연결 코드를 입력하세요. 위 코드는 설명을 위한 예시입니다.'}};
const tabs=[...document.querySelectorAll('[data-screen]')];
function selectScreen(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});const s=screens[tab.dataset.screen];const img=document.querySelector('#product-screen');img.src=s.src;img.alt=s.alt;document.querySelector('#screen-title').textContent=s.title;document.querySelector('#screen-description').textContent=s.description;document.querySelector('#screen-panel').setAttribute('aria-labelledby',tab.id)}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectScreen(tab));tab.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight'||e.key==='ArrowDown')next=(index+1)%tabs.length;if(e.key==='ArrowLeft'||e.key==='ArrowUp')next=(index+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();selectScreen(tabs[next]);tabs[next].focus()}})});
const dialog=document.querySelector('#screen-dialog');
document.querySelector('#expand-screen').addEventListener('click',()=>{const current=document.querySelector('#product-screen');const enlarged=document.querySelector('#dialog-image');enlarged.src=current.src;enlarged.alt=current.alt;dialog.showModal()});
document.querySelector('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
let inquiry='';const status=document.querySelector('#contact-status');document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const studio=String(data.get('studio')).trim();if(!studio){e.currentTarget.elements.studio.setCustomValidity('매장명을 입력해 주세요.');e.currentTarget.elements.studio.reportValidity();return}inquiry=`클라우드보드 파일럿 도입 문의\n\n매장명: ${studio}\n디스플레이 수: ${data.get('screens')}\n\n문의 내용:\n${String(data.get('message')).trim() || '파일럿 참여 조건과 설치 방법을 안내받고 싶습니다.'}`;status.textContent='메일 앱에서 내용을 확인하고 발송해 주세요. 열리지 않으면 내용을 복사해 vividxxxxx@gmail.com으로 보내주세요.';document.querySelector('#copy-inquiry').hidden=false;window.location.href=`mailto:vividxxxxx@gmail.com?subject=${encodeURIComponent('[클라우드보드] '+studio+' 도입 문의')}&body=${encodeURIComponent(inquiry)}`});document.querySelector('[name=studio]').addEventListener('input',e=>e.target.setCustomValidity(''));
document.querySelector('#copy-inquiry').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(inquiry);status.textContent='문의 내용을 복사했습니다. vividxxxxx@gmail.com으로 보내주세요.'}catch{status.textContent='자동 복사를 사용할 수 없습니다. 아래 내용을 선택해 복사해 주세요.';let fallback=document.querySelector('#copy-fallback');if(!fallback){fallback=document.createElement('textarea');fallback.id='copy-fallback';fallback.readOnly=true;fallback.setAttribute('aria-label','복사할 문의 내용');document.querySelector('#contact-form').append(fallback)}fallback.value=inquiry;fallback.focus();fallback.select()}});
